insert into public.product_updates (title, description, published_on) values
($$Novità ha ora una pagina tutta sua$$, $$Non più una card in Dashboard: "Novità" è adesso una voce del menu principale, con tutte le modifiche fatte a Hinthial in ordine, dalla più recente.$$, '2026-09-13'),
($$Scegli tu quali voci vedere nel menu, e in che ordine$$, $$In Impostazioni > Aspetto puoi decidere quali voci mostrare nel menu principale e riordinarle a piacere --- utile se non usi tutte le sezioni allo stesso modo.$$, '2026-09-13'),
($$Scatta foto usa davvero la fotocamera (o la webcam)$$, $$Su smartphone, "Scatta foto" e "Carica foto" fanno finalmente cose diverse: uno apre la fotocamera, l'altro la galleria. Su computer, "Scatta foto" accende la webcam con un'anteprima dal vivo.$$, '2026-09-13');
